arguments.command:
cd /tmp/vally-eval-trial-uTahvK && mkdir -p tests/CheckoutPricing.UnitTests/Checkout && cat > src/CheckoutPricing.Application/CalculatePayableTotal.cs <<'E'
namespace CheckoutPricing.Application;

public enum CustomerTier { Standard, Gold }

public sealed class CalculatePayableTotalHandler
{
    public decimal Handle(CustomerTier tier, decimal orderSubtotal) => orderSubtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/Checkout/GoldCustomerDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests.Checkout;

public sealed class GoldCustomerDiscountTests
{
    [Fact]
    public void Gold_customer_with_a_100_00_subtotal_pays_95_00()
    {
        var handler = new CalculatePayableTotalHandler();

        var payable = handler.Handle(CustomerTier.Gold, 100.00m);

        Assert.Equal(95.00m, payable);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | tail -25

